\u093c\\u0928 \\u092e\\u0948\\u0915\\u0947\\u0928\\u093f\\u0915 \\u0915\\u094b \\u0915\\u0949\\u0928\\u094d\\u092b\\u093c\\u093f\\u0917\\u0930, \\u091f\\u0949\\u0917\\u0932 \\u092f\\u093e \\u092e\\u0949\\u0921\\u094d\\u092f\\u0942\\u0932\\u0947\\u091f \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0940 \\u0938\\u0941\\u0935\\u093f\\u0927\\u093e \\u0909\\u092a\\u0932\\u092c\\u094d\\u0927 \\u0939\\u0948\\u0964\", \"Hierarchical \\u0914\\u0930 Non-Hierarchical \\u090f\\u091c\\u0947\\u0902\\u091f\\u094d\\u0938 \\u0915\\u094b \\u0938\\u092e\\u093e\\u0928 \\u0911\\u092c\\u094d\\u091c\\u0930\\u094d\\u0935\\u0947\\u0936\\u0928 \\u0938\\u094d\\u092a\\u0947\\u0938, \\u090f\\u0915\\u094d\\u0936\\u0928 \\u0938\\u094d\\u092a\\u0947\\u0938 \\u0914\\u0930 \\u0924\\u0941\\u0932\\u0928\\u0940\\u092f \\u092e\\u0949\\u0921\\u0932 \\u0915\\u094d\\u0937\\u092e\\u0924\\u093e (parameter size) \\u092a\\u0930 \\u091f\\u094d\\u0930\\u0947\\u0928/\\u0907\\u0935\\u0948\\u0932\\u094d\\u092f\\u0942\\u090f\\u091f \\u0915\\u093f\\u092f\\u093e \\u091c\\u093e \\u0938\\u0915\\u0924\\u093e \\u0939\\u0948\\u0964\", \"\\u0938\\u0930\\u094d\\u0935\\u093e\\u0907\\u0935\\u0932 \\u0905\\u0935\\u0927\\u093f \\u0915\\u094b \\u091f\\u094d\\u0930\\u093f\\u0917\\u0930 \\u092a\\u0949\\u0907\\u0902\\u091f \\u0938\\u0947 \\u090f\\u092a\\u093f\\u0938\\u094b\\u0921 \\u091f\\u0930\\u094d\\u092e\\u093f\\u0928\\u0947\\u0936\\u0928 \\u0924\\u0915 \\u0938\\u091f\\u0940\\u0915 \\u0930\\u0942\\u092a \\u0938\\u0947 \\u092e\\u093e\\u092a\\u093e \\u091c\\u093e \\u0938\\u0915\\u0924\\u093e \\u0939\\u0948\\u0964\"]}", "origin": "completion"}, "llm_response_id": "YE3UatbvHP-c4_UP6tOx8AQ", "security_risk": "UNKNOWN", "kind": "ActionEvent", "source_event_index": 10}
